// ---------------------------------------------------------------------------
// Real optician practices in and around each town, from each optician's own
// store and booking systems. Generated by scripts/snapshot-stores.ts.
// Brands not covered by a live lookup fall back to the hand-checked
// storeLocations list in opticians.ts.
// ---------------------------------------------------------------------------

import snapshotJson from "./store-snapshot.json";
import specsaversJson from "./specsavers-stores.json";
import { opticians, type OpticianBrand } from "./opticians";
import { locations, type UKLocation } from "./locations";

export type SnapshotStore = {
  name: string;
  address: string;
  postcode: string;
  phone: string;
  lat?: number;
  lng?: number;
  bookingUrl: string;
  distanceM: number;
};

type StoreSnapshot = {
  generated: string;
  brands: string[];
  towns: Record<string, Record<string, SnapshotStore[]>>;
};

const snapshot = snapshotJson as StoreSnapshot;

// Specsavers blocks automated lookups, so its town stores were read from each
// town's page on specsavers.co.uk and kept in their own file.
const specsavers = specsaversJson as { generated: string; stores: Record<string, SnapshotStore[]> };

/** Live result for a brand and town, or undefined if we have no lookup for it */
function liveStores(brand: string, town: string): SnapshotStore[] | undefined {
  if (brand === "specsavers") return specsavers.stores[town];
  return isLiveBrand(brand) ? snapshot.towns[town]?.[brand] : undefined;
}

/** ISO date the snapshot was taken */
export const SNAPSHOT_DATE = snapshot.generated;

/** True when the brand's practices come from a live lookup */
export function isLiveBrand(brand: string): boolean {
  return snapshot.brands.includes(brand);
}

/** Practices for a brand in and around a town (empty if none, or if not a live brand) */
export function storesFor(brand: string, town: string): SnapshotStore[] {
  return liveStores(brand, town) ?? [];
}

/** Whether we list a practice for this brand in and around the town.
 *  Uses the live snapshot when it has a result for the brand and town, and
 *  falls back to the hand-checked storeLocations list otherwise. */
export function brandInTown(brand: OpticianBrand, town: string): boolean {
  const live = liveStores(brand.slug, town);
  if (live) return live.length > 0;
  return brand.storeLocations.includes(town);
}

/** Other brands with a practice listed in and around the town */
export function brandsInTown(town: string, exclude?: string): OpticianBrand[] {
  return opticians.filter((o) => o.slug !== exclude && brandInTown(o, town));
}

function miles(a: UKLocation, b: UKLocation): number {
  const R = 3958.8;
  const toRad = (x: number) => (x * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLon = toRad(b.lng - a.lng);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

/** Nearest towns (by straight-line distance) where the brand has a practice */
export function nearestBrandTowns(
  brand: OpticianBrand,
  from: UKLocation,
  count = 4
): { location: UKLocation; miles: number }[] {
  return locations
    .filter((l) => l.slug !== from.slug && brandInTown(brand, l.slug))
    .map((l) => ({ location: l, miles: Math.round(miles(from, l)) }))
    .sort((a, b) => a.miles - b.miles)
    .slice(0, count);
}
